//! Schema generation behaviour carried over from schemars 0.8.
//!
//! The tool parameter schemas sent to model providers, and the committed config,
//! hook and app-server protocol schemas, were generated by schemars 0.8. schemars 1
//! changed the shape of that output in small ways that no setting turns back, so
//! [`Compat08`] is a transform that puts each one back. Without it nothing fails:
//! tools still register, fixtures merely drift, and the model sees a different
//! description string than before.
//!
//! What it restores:
//! - doc comments joined into one line per paragraph (1.x keeps the line breaks);
//! - `required` sorted (0.8 stored it in a `BTreeSet`; 1.x keeps declaration order);
//! - `minimum`, `maximum` and friends as floating point (`0.0`, not `0`);
//! - no `minimum`/`maximum` on `u8`, `u16`, `i8` and `i16` fields (1.x adds the type's range);
//! - a string tag as `"enum": ["tag"]` rather than `"const": "tag"`, unless
//!   [`Compat08::keeping_const`] says the `const` was written on purpose;
//! - with [`Compat08::without_null`], `Option<T>` written as plain `T`
//!   (`option_add_null_type = false`, a setting 1.x removed).

use schemars::Schema;
use schemars::transform::Transform;
use schemars::transform::transform_subschemas;
use serde_json::Map;
use serde_json::Number;
use serde_json::Value;
use serde_json::json;

/// Set on a schema whose `null` was written on purpose; [`Compat08::without_null`]
/// leaves that schema alone and removes the marker.
pub const KEEP_NULL: &str = "x-atlas-keep-null";

const FLOAT_KEYWORDS: [&str; 5] = [
    "minimum",
    "maximum",
    "exclusiveMinimum",
    "exclusiveMaximum",
    "multipleOf",
];

#[derive(Debug, Clone, Copy)]
pub struct Compat08 {
    strip_option_null: bool,
    const_to_enum: bool,
}

impl Compat08 {
    /// Keeps the `"null"` branch schemars 1 adds for `Option<T>`; 0.8's default.
    pub const fn with_null() -> Self {
        Self {
            strip_option_null: false,
            const_to_enum: true,
        }
    }

    /// Removes the `"null"` branch, as 0.8's `option_add_null_type = false` did.
    ///
    /// This cannot tell a derived `Option` from a `null` written by hand, so a
    /// schema that must keep an explicit `null` is marked with [`KEEP_NULL`].
    pub const fn without_null() -> Self {
        Self {
            strip_option_null: true,
            const_to_enum: true,
        }
    }

    /// Leaves `const` alone, for schemas that spell it out by hand.
    pub const fn keeping_const(mut self) -> Self {
        self.const_to_enum = false;
        self
    }
}

impl Transform for Compat08 {
    fn transform(&mut self, schema: &mut Schema) {
        transform_subschemas(self, schema);
        let Some(object) = schema.as_object_mut() else {
            return;
        };
        for key in ["description", "title"] {
            if let Some(Value::String(text)) = object.get_mut(key) {
                *text = join_doc_lines(text);
            }
        }
        if let Some(Value::Array(required)) = object.get_mut("required") {
            required.sort_by(|a, b| a.as_str().cmp(&b.as_str()));
        }
        strip_small_int_range(object);
        for key in FLOAT_KEYWORDS {
            if let Some(value) = object.get_mut(key)
                && let Some(float) = value.as_f64()
                && let Some(number) = Number::from_f64(float)
            {
                *value = Value::Number(number);
            }
        }
        if self.const_to_enum
            && object.get("type").is_some_and(|ty| ty == "string")
            && object.get("const").is_some_and(Value::is_string)
            && let Some(tag) = object.remove("const")
        {
            object.insert("enum".to_string(), Value::Array(vec![tag]));
        }
        let keep_null = object.remove(KEEP_NULL).is_some();
        if self.strip_option_null && !keep_null {
            strip_null(schema);
        }
    }
}

/// 0.8 turned a doc comment into one line per paragraph, paragraphs separated by
/// a blank line. 1.x keeps the author's line wrapping.
fn join_doc_lines(text: &str) -> String {
    text.trim()
        .split("\n\n")
        .map(|paragraph| {
            paragraph
                .lines()
                .map(str::trim)
                .collect::<Vec<_>>()
                .join(" ")
        })
        .filter(|paragraph| !paragraph.is_empty())
        .collect::<Vec<_>>()
        .join("\n\n")
}

/// 1.x spells out the range of the small integer types; 0.8 only named the format.
fn strip_small_int_range(object: &mut Map<String, Value>) {
    let range = match object.get("format").and_then(Value::as_str) {
        Some("uint8") => (0, 255),
        Some("uint16") => (0, 65535),
        Some("int8") => (-128, 127),
        Some("int16") => (-32768, 32767),
        _ => return,
    };
    for (key, bound) in [("minimum", range.0), ("maximum", range.1)] {
        // Unsigned types carried `minimum: 0` in 0.8 as well, so only the maximum
        // and the signed minimum are new.
        let unsigned_minimum = key == "minimum" && bound == 0;
        if !unsigned_minimum && object.get(key).and_then(Value::as_i64) == Some(bound) {
            object.remove(key);
        }
    }
}

fn strip_null(schema: &mut Schema) {
    let Some(object) = schema.as_object_mut() else {
        return;
    };
    strip_null_type(object);
    strip_null_enum(object);
    let null = json!({ "type": "null" });
    let Some(Value::Array(branches)) = object.get_mut("anyOf") else {
        return;
    };
    if branches.len() < 2 || !branches.contains(&null) {
        return;
    }
    branches.retain(|branch| branch != &null);
    if branches.len() == 1 {
        let only = branches.remove(0);
        object.remove("anyOf");
        merge_sole_branch(object, only);
    }
}

fn strip_null_type(object: &mut Map<String, Value>) {
    let Some(Value::Array(types)) = object.get_mut("type") else {
        return;
    };
    if types.len() < 2 {
        return;
    }
    types.retain(|ty| ty != "null");
    if types.len() == 1 {
        let ty = types.remove(0);
        object.insert("type".to_string(), ty);
    }
}

fn strip_null_enum(object: &mut Map<String, Value>) {
    if let Some(Value::Array(values)) = object.get_mut("enum")
        && values.len() > 1
    {
        values.retain(|value| !value.is_null());
    }
}

/// Folds the single remaining `anyOf` branch back into its parent.
///
/// A bare `$ref` cannot take siblings in draft-07, so when the parent carries
/// other keywords (a description, say) the reference moves into `allOf`, which is
/// how schemars 0.8 wrote a documented `Option<Struct>` field.
fn merge_sole_branch(parent: &mut Map<String, Value>, only: Value) {
    let Value::Object(only) = only else {
        return;
    };
    if parent.is_empty() {
        *parent = only;
    } else if only.len() == 1 && only.contains_key("$ref") {
        parent.insert("allOf".to_string(), Value::Array(vec![Value::Object(only)]));
    } else {
        for (key, value) in only {
            parent.entry(key).or_insert(value);
        }
    }
}

/// For `#[schemars(transform = ...)]` on a struct that `#[serde(flatten)]`s a map.
///
/// schemars 0.8 took `additionalProperties` from the flattened map only when the
/// struct had `deny_unknown_fields`, and left it out otherwise; schemars 1 takes
/// it from the map either way. This puts the keyword back to absent.
pub fn drop_additional_properties(schema: &mut Schema) {
    if let Some(object) = schema.as_object_mut() {
        object.remove("additionalProperties");
    }
}
